// canary-local/voice/voice.js — the Canary Voice sound board's UI.
//
// Hand-written. The sound itself is window.VOICE_DATA, which voice-data.js
// (loaded first, GENERATED by canary-local/tools/gen_voice_preview.mjs from the
// firmware's voice_score.h) defines; this file plays those frames verbatim and
// owns no audio math. It used to be an inline <script> in a generated page; as
// a file it runs under the page's Content-Security-Policy (script-src 'self',
// written by canary-local/tools/gen_csp.py) with no hash.
(() => {
  "use strict";
  const D = window.VOICE_DATA;
  const CAT_VAR = ["--interaction","--ambient","--notice","--wake","--alert"];

  // UI copy (human-facing prose; the SOUND is all from VOICE_DATA).
  const META = {
    Alarm:{name:"Alarm", desc:"Alert / Tamper. Re-voices every 30 s until acknowledged.", spec:"10 pulses · 2.6/3.1 kHz · IEC"},
    Warn:{name:"Warn", desc:"A fault — witness lost, chain failed. Not the intruder shape.", spec:"3 slow pulses · 1.8 kHz"},
    AllClear:{name:"All-clear", desc:"The worst state falls back to quiet. Resolution has a sound.", spec:"falling · 1.3 → 0.9 kHz"},
    Boot:{name:"Boot", desc:"Power-on — “the canary wakes.” Our startup signature.", spec:"C6→E6 · G6→C7 · warble"},
    JoinSuccess:{name:"Joined", desc:"You're in the fleet. Earned once, at onboarding.", spec:"C6·E6·G6·C7 arpeggio"},
    Sunrise:{name:"Sunrise", desc:"The gentle wake chirp. Sounds through the night by design.", spec:"C6→E6 → E6→G6 · warble"},
    Heartbeat:{name:"Heartbeat", desc:"Once-a-minute, all-verified. Felt more than heard.", spec:"C6 · 420 ms swell"},
    AckConfirm:{name:"Acknowledge", desc:"Long-press registered — a warm nod that resolves.", spec:"C6 → G6 · perfect fifth"},
    PageTurn:{name:"Page turn", desc:"Paging through your Canaries on the watch.", spec:"E6 · A6 · light pips"},
    MuteOn:{name:"Mute on", desc:"Silencing one witness. Falling = going quiet.", spec:"G6 → D6 · descending"},
    MuteOff:{name:"Mute off", desc:"The mute lifts. The mirror of muting — ascending.", spec:"D6 → G6 · ascending"},
    Tap:{name:"Tap", desc:"The lightest “heard you.” In the palette; not auto-wired.", spec:"A6 · 42 ms pluck"},
  };
  const GROUPS = {
    "grid-alerts":["Alarm","Warn","AllClear"],
    "grid-identity":["Boot","JoinSuccess","Sunrise","Heartbeat"],
    "grid-interactions":["AckConfirm","PageTurn","MuteOn","MuteOff","Tap"],
  };
  const PLAY_SVG = '<svg class="play-ic" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M4 3l9 5-9 5V3z" fill="currentColor"/></svg>';

  let volume = 3, night = false;
  const cards = {};

  function peakFor(id){ return D.peak[D.voices[id].cat][volume][night?1:0]; }

  function buildCards(){
    for(const [gid, ids] of Object.entries(GROUPS)){
      const grid = document.getElementById(gid);
      for(const id of ids){
        if(!D.voices[id]) continue;
        const cat = D.voices[id].cat, m = META[id] || {name:id, desc:"", spec:""};
        const btn = document.createElement("button");
        btn.className = "card"; btn.type = "button";
        btn.style.setProperty("--cat", `var(${CAT_VAR[cat]})`);
        btn.setAttribute("aria-label", `Play ${m.name}`);
        btn.innerHTML =
          `<div class="card-top"><span class="card-name">${m.name}</span><span class="cat-tag">${D.catNames[cat]}</span></div>`+
          `<div class="card-desc">${m.desc}</div>`+
          `<div class="card-spec mono">${PLAY_SVG}<span>${m.spec}</span></div>`+
          `<div class="meter-row"><span class="meter"><i></i></span><span class="duty mono"></span></div>`;
        btn.addEventListener("click", () => play(id, btn));
        grid.appendChild(btn);
        cards[id] = { btn, fill: btn.querySelector(".meter i"), duty: btn.querySelector(".duty") };
      }
    }
    refreshMeters();
  }
  function refreshMeters(){
    for(const id in cards){
      const d = peakFor(id);
      cards[id].fill.style.width = (d/128*100) + "%";
      cards[id].duty.textContent = d===0 ? "silent" : `duty ${d}/128`;
      cards[id].btn.classList.toggle("silent", d===0);
    }
  }

  // ── Audio: play firmware-rendered frames verbatim ──────────────────────
  let ac=null, master=null, analyzer=null, active=0, rafId=0;
  const STEP = 0.006;  // frames are emitted at the firmware's 6 ms control tick
  function ensureAudio(){
    if(ac) return;
    ac = new (window.AudioContext||window.webkitAudioContext)();
    master = ac.createGain(); master.gain.value = 0.16;
    const lp = ac.createBiquadFilter(); lp.type="lowpass"; lp.frequency.value=5600; lp.Q.value=0.4;
    // createAnalyser is the Web Audio API's own method name, a vendor
    // identifier that the US-spelling rule (AGENTS.md rule 3b) keeps as
    // spelled: AudioContext has no createAnalyzer, and calling it threw on
    // the first card click and left the board silent with an empty scope.
    analyzer = ac.createAnalyser(); analyzer.fftSize = 2048;
    master.connect(lp); lp.connect(analyzer); analyzer.connect(ac.destination);
  }
  function play(id, btn){
    ensureAudio(); if(ac.state==="suspended") ac.resume();
    const peak = peakFor(id);
    setNowPlaying(id, peak);
    if(peak===0){ btn.animate([{opacity:.62},{opacity:1},{opacity:.62}],{duration:420}); return; }
    const frames = D.voices[id].frames, gscale = peak/128;
    const osc = ac.createOscillator(); osc.type="square";
    const g = ac.createGain(); g.gain.value = 0;
    osc.connect(g); g.connect(master);
    const t0 = ac.currentTime + 0.02;
    for(let i=0;i<frames.length;i++){
      const at = t0 + i*STEP, f = frames[i][0], a = frames[i][1];
      if(f>0){ osc.frequency.setValueAtTime(f, at); g.gain.setValueAtTime(Math.max(0, gscale*a/256), at); }
      else { g.gain.setValueAtTime(0, at); }
    }
    const end = t0 + frames.length*STEP;
    g.gain.setValueAtTime(0, end);
    osc.start(t0); osc.stop(end + 0.02);
    active++; btn.classList.add("playing"); startScope();
    osc.onended = () => { active=Math.max(0,active-1); btn.classList.remove("playing"); if(active===0) resetNowPlaying(); };
  }

  const npName=document.getElementById("npName"), npSub=document.getElementById("npSub");
  function setNowPlaying(id, peak){
    npName.textContent = (META[id]||{}).name || id;
    npName.style.color = `var(${CAT_VAR[D.voices[id].cat]})`;
    npSub.textContent = peak===0 ? (night?"silenced at night":"silent at this volume")
      : `${D.catNames[D.voices[id].cat].toLowerCase()} · duty ${peak}/128${night?" · night":""}`;
  }
  function resetNowPlaying(){ npName.textContent="Ready"; npName.style.color=""; npSub.textContent="tap a signature to hear it"; }

  // ── Oscilloscope ───────────────────────────────────────────────────────
  const cv=document.getElementById("scope"), cx=cv.getContext("2d");
  const reduce = matchMedia("(prefers-reduced-motion:reduce)").matches;
  const css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
  function fitCanvas(){ const r=cv.getBoundingClientRect(), dpr=Math.min(2,devicePixelRatio||1); cv.width=Math.round(r.width*dpr); cv.height=Math.round(r.height*dpr); cx.setTransform(dpr,0,0,dpr,0,0); }
  function drawScope(){
    const w=cv.getBoundingClientRect().width, h=cv.getBoundingClientRect().height;
    cx.clearRect(0,0,w,h);
    cx.strokeStyle=css("--scope-grid"); cx.lineWidth=1; cx.beginPath(); cx.moveTo(0,h/2); cx.lineTo(w,h/2); cx.stroke();
    if(!analyzer) return;
    const buf=new Uint8Array(analyzer.fftSize); analyzer.getByteTimeDomainData(buf);
    cx.lineWidth=2; cx.strokeStyle=css("--scope-line"); cx.lineJoin="round"; cx.beginPath();
    for(let i=0;i<buf.length;i++){ const x=i/(buf.length-1)*w, y=h/2+(buf[i]-128)/128*(h*0.42); i?cx.lineTo(x,y):cx.moveTo(x,y); }
    cx.stroke(); cx.shadowBlur=10; cx.shadowColor=css("--scope-line"); cx.stroke(); cx.shadowBlur=0;
  }
  function startScope(){ if(rafId||reduce){ if(reduce) drawScope(); return; } const loop=()=>{ drawScope(); if(active>0) rafId=requestAnimationFrame(loop); else { rafId=0; setTimeout(drawScope,60);} }; rafId=requestAnimationFrame(loop); }

  // ── Controls ───────────────────────────────────────────────────────────
  const volseg=document.getElementById("volseg");
  function setVol(v){ volume=v; [...volseg.children].forEach(b=>b.setAttribute("aria-pressed",(+b.dataset.v===v)?"true":"false")); refreshMeters(); }
  volseg.addEventListener("click", e=>{ const b=e.target.closest("button"); if(b) setVol(+b.dataset.v); });
  const nightBtn=document.getElementById("nightBtn"), nightLbl=document.getElementById("nightLbl"), hint=document.getElementById("hint");
  nightBtn.addEventListener("click", ()=>{ night=!night; nightBtn.dataset.night=night; nightBtn.setAttribute("aria-pressed",night);
    nightLbl.textContent=night?"Quiet hours":"Daytime";
    hint.textContent=night?"At night the gentle voices fall silent — only Wake and Alert sound.":"The volume model runs live — watch each duty meter change.";
    refreshMeters(); });
  document.getElementById("themebtn").addEventListener("click", ()=>{
    const cur=document.documentElement.getAttribute("data-theme")||(matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light");
    document.documentElement.setAttribute("data-theme", cur==="dark"?"light":"dark");
    if(active===0) setTimeout(drawScope,0);
  });

  document.getElementById("prov").textContent = "generated from firmware/projects/canary-display/include/canary/hal/voice_score.h · "
    + Object.keys(D.voices).length + " signatures · CI-gated";
  buildCards(); setVol(3); fitCanvas(); drawScope();
  addEventListener("resize", ()=>{ fitCanvas(); if(active===0) drawScope(); });
})();
